class Solution:
    def minDeletionSize(self, strs):
        n, w = len(strs), len(strs[0])
        best = w
        for mask in range(1 << w):
            cols = [c for c in range(w) if mask >> c & 1]
            proj = ["".join(s[c] for c in cols) for s in strs]
            if all(proj[i] <= proj[i + 1] for i in range(n - 1)):
                best = min(best, w - len(cols))
        return best

