class Solution {
public:
    int minDeletionSize(vector<string>& strs) {
        int n = strs.size(), w = strs[0].size(), best = w;
        for (int mask = 0; mask < (1 << w); ++mask) {
            vector<string> proj(n);
            for (int i = 0; i < n; ++i)
                for (int c = 0; c < w; ++c)
                    if (mask >> c & 1) proj[i] += strs[i][c];
            bool ok = true;
            for (int i = 0; i + 1 < n && ok; ++i)
                if (proj[i] > proj[i + 1]) ok = false;
            if (ok) best = min(best, w - __builtin_popcount(mask));
        }
        return best;
    }
};

