class Solution {
    public int minDeletionSize(String[] strs) {
        int n = strs.length, w = strs[0].length(), best = w;
        for (int mask = 0; mask < (1 << w); mask++) {
            String[] proj = new String[n];
            for (int i = 0; i < n; i++) {
                StringBuilder sb = new StringBuilder();
                for (int c = 0; c < w; c++)
                    if ((mask >> c & 1) == 1) sb.append(strs[i].charAt(c));
                proj[i] = sb.toString();
            }
            boolean ok = true;
            for (int i = 0; i + 1 < n; i++)
                if (proj[i].compareTo(proj[i + 1]) > 0) { ok = false; break; }
            if (ok) best = Math.min(best, w - Integer.bitCount(mask));
        }
        return best;
    }
}

