        n, w = len(strs), len(strs[0])
        cut = [False] * n
        ans = 0
        for c in range(w):
            bad = any(not cut[i] and strs[i][c] > strs[i + 1][c] for i in range(n - 1))
            if bad:
                ans += 1
                continue
            for i in range(n - 1):
                if not cut[i] and strs[i][c] < strs[i + 1][c]:
                    cut[i] = True
        return ans

